# Frame layout (12 bytes total):
#   [0]  0x55
#   [1]  0xAA
#   [2]  ch (ASCII)
#   [3]  picstop_low32 (LE, byte 0)
#   [4]  picstop_low32 (LE, byte 1)
#   [5]  picstop_low32 (LE, byte 2)
#   [6]  picstop_low32 (LE, byte 3)
#   [7]  tof (LE, byte 0)
#   [8]  tof (LE, byte 1)
#   [9]  tof (LE, byte 2)
#   [10] tof (LE, byte 3)
#   [11] CRC-8 Dallas/Maxim over bytes [2..10]
#
# Output: one line per valid frame:
#   offset  picstop_low32(hex)  picstop_low32(dec)  tof(hex)  tof(dec)  ch  ts_low32_only(s)
#
# Notes:
# - Scans byte-by-byte for 0x55AA
# - Verifies CRC-8 (Dallas/Maxim: poly 0x31, reflected 0x8C in code, init 0x00)
# - Optional channel whitelist (--channels A B). If omitted, accepts any ch.
# - Timestamp uses only low32 (no rollover extension here; main decoder will handle that)

import argparse
import sys

PS_PER_TICK_DEFAULT = 100_000_000  # 100 microseconds in picoseconds
HDR0 = 0x55
HDR1 = 0xAA
FRAME_LEN = 12

def parse_args():
    p = argparse.ArgumentParser(
        description="Dump 0x55AA+CRC frames to text (debug). ID=v2025-09-29.2"
    )
    p.add_argument("--infile", required=True, help="Captured binary file")
    p.add_argument("--outfile", required=True, help="Output text file")
    p.add_argument(
        "--ps-per-tick",
        type=int,
        default=PS_PER_TICK_DEFAULT,
        help="Picoseconds per tick (default 100,000,000)",
    )
    p.add_argument(
        "--channels",
        nargs="+",
        help="Optional channel whitelist (e.g., A B). If omitted, accept any byte.",
    )
    p.add_argument(
        "--max-lines",
        type=int,
        default=1_000_000,
        help="Maximum lines to write (safety cap).",
    )
    return p.parse_args()

def crc8_maxim(payload: bytes) -> int:
    # Dallas/Maxim CRC-8: poly 0x31 (reflected 0x8C), init 0x00, refIn/Out true
    crc = 0x00
    for b in payload:
        crc ^= b
        for _ in range(8):
            if crc & 0x01:
                crc = (crc >> 1) ^ 0x8C
            else:
                crc >>= 1
    return crc & 0xFF

def main():
    args = parse_args()

    try:
        with open(args.infile, "rb") as f:
            data = f.read()
    except Exception as e:
        print(f"Failed to read input file: {e}", file=sys.stderr)
        sys.exit(1)

    n = len(data)
    out_lines = []
    i = 0

    ok = 0
    crc_fail = 0
    scanned = 0

    def fmt_line(offset: int, ch_byte: int, picstop_low: int, tof: int) -> str:
        ch = chr(ch_byte) if 32 <= ch_byte <= 126 else f"0x{ch_byte:02X}"
        ts_ps = (picstop_low * args.ps_per_tick) - tof
        ts_s = ts_ps / 1e12
        return (
            f"{offset:10d}  "
            f"0x{picstop_low:08X}  {picstop_low:10d}  "
            f"0x{tof:08X}  {tof:10d}  "
            f"{ch}  "
            f"{ts_s:.12f}"
        )

    ch_whitelist = None
    if args.channels:
        ch_whitelist = set()
        for s in args.channels:
            if len(s) == 1:
                ch_whitelist.add(ord(s))
            else:
                try:
                    val = int(s, 0)
                    if 0 <= val <= 255:
                        ch_whitelist.add(val)
                except Exception:
                    pass

    while i + FRAME_LEN <= n:
        # Seek header
        if data[i] != HDR0 or data[i + 1] != HDR1:
            i += 1
            scanned += 1
            continue

        end = i + FRAME_LEN
        frame = data[i:end]

        # parse fields
        ch_byte = frame[2]
        payload = frame[2:11]     # ch + picstop(4) + tof(4)
        crc_file = frame[11]
        crc_calc = crc8_maxim(payload)

        # channel filter early
        if ch_whitelist is not None and ch_byte not in ch_whitelist:
            i += 1
            scanned += 1
            continue

        if crc_calc != crc_file:
            crc_fail += 1
            i += 1
            scanned += 1
            continue

        # Valid frame
        picstop_low = int.from_bytes(frame[3:7], "little", signed=False)
        tof = int.from_bytes(frame[7:11], "little", signed=False)
        out_lines.append(fmt_line(i, ch_byte, picstop_low, tof))
        ok += 1
        i = end  # step by 12 when aligned

    # Write output
    try:
        with open(args.outfile, "w", encoding="utf-8", newline="\n") as out:
            out.write(
                "# offset  picstop_low32(hex)  picstop_low32(dec)  tof(hex)  tof(dec)  ch  ts_low32_only(s)\n"
            )
            for line in out_lines[: args.max_lines]:
                out.write(line + "\n")
    except Exception as e:
        print(f"Failed to write output: {e}", file=sys.stderr)
        sys.exit(1)

    print(f"Wrote {min(len(out_lines), args.max_lines)} frames to {args.outfile}", file=sys.stderr)
    print(f"Frames OK={ok}, CRC_fail={crc_fail}, bytes_scanned_for_resync={scanned}", file=sys.stderr)

if __name__ == "__main__":
    main()


